const body = $json.body || $json;
const payload = body.payload || body;
const qa = payload.questions_and_answers || [];
const answer = (needle) => {
  const hit = qa.find(x => String(x.question || '').toLowerCase().includes(needle));
  return hit ? hit.answer : '';
};
// Real Calendly payloads nest it under calendar_event; scheduled_event/start_time are defensive
// fallbacks in case the shape differs - confirm against a real test booking and simplify once known.
const startTime = (payload.calendar_event && payload.calendar_event.start_time)
  || (payload.scheduled_event && payload.scheduled_event.start_time)
  || payload.start_time
  || null;
return { json: {
  name: payload.name || (payload.invitee && payload.invitee.name) || 'Unknown',
  email: payload.email || (payload.invitee && payload.invitee.email) || '',
  q1_process: answer('manual process'),
  q2_people: answer('how many people'),
  q3_tried: answer('what have you tried'),
  start_time: startTime
} };

const invitee = $('Extract Invitee').first().json;
const matches = $input.all().map(i => i.json).filter(l => l && l.id);
const lead = matches[0] || null;
return { json: {
  ...invitee,
  lead_id: lead ? lead.id : null,
  lead_company: lead ? lead.company : null,
  lead_role: lead ? lead.role : null,
  lead_channel: lead ? lead.channel : null,
  lead_notes: lead ? lead.context_notes : null
} };

const d = $('Merge Lead Match').first().json;
let waitIso = new Date().toISOString();
if (d.start_time) {
  const start = new Date(d.start_time);
  const briefAt = new Date(start.getTime() - 2 * 60 * 60 * 1000);
  waitIso = briefAt.toISOString();
}
return { json: { ...d, brief_at: waitIso } };

const d = $json;
const system = `You write a short pre-call brief for Daniel Zabaleta, founder of Power Flow, before a discovery call. Rules:
- Exactly 5 lines, plain text, no markdown headers.
- Line 1: who they are (name, and company/role if known).
- Line 2-3: read between the lines of their intake answers to name the likely real bottleneck.
- Line 4: one sharp question Daniel should ask early to confirm or kill that hypothesis.
- Line 5: one risk or watch-out for this call (budget signal, vague answer, urgency).
No fluff, no 'I hope this helps', no preamble. Output only the 5 lines.`;
const userContent = `Invitee: ${d.name} (${d.email})
Company on file: ${d.lead_company || 'unknown'}
Role on file: ${d.lead_role || 'unknown'}
Source channel: ${d.lead_channel || 'unknown'}
Prior notes: ${d.lead_notes || 'none'}

Intake answers:
1. Most manual process today: ${d.q1_process || 'not answered'}
2. People who touch it: ${d.q2_people || 'not answered'}
3. What they have tried: ${d.q3_tried || 'not answered'}`;
return { json: {
  ...d,
  gemini_body: {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: userContent }] }],
    generationConfig: { maxOutputTokens: 512 }
  }
} };

const src = $('Build Gemini Body').first().json;
const resp = $json;
let brief = '';
try { brief = resp.candidates[0].content.parts[0].text.trim(); } catch (e) { brief = 'BRIEF FAILED, revisar ejecucion'; }
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<div style="font-family:Inter,Arial,sans-serif;padding:20px">`
  + `<h3>Call prep — ${esc(src.name)}</h3>`
  + `<p style="white-space:pre-wrap">${esc(brief)}</p><hr/>`
  + `<p style="font-size:13px;color:#565C6B"><b>Intake answers</b><br/>`
  + `1. ${esc(src.q1_process)}<br/>2. ${esc(src.q2_people)}<br/>3. ${esc(src.q3_tried)}</p></div>`;
return { json: { subject: `Call prep: ${src.name}`, html } };
